#!/usr/bin/env bash
set -Euo pipefail

MANAGER_VERSION="1.4.2"
ENGINE_VERSION="1.4.0"
PROTOCOL_NAME="SSH_XHTTP - NEW GOLDEN"
ENGINE_SHA_AMD64="446960ef13353d3f186721bc6b8426116e75a56af12689317e9b3d6f99ce77da"
ENGINE_SHA_ARM64="983174005257103290f982d0863c971c3cd3ed7c19e6067517974b1d97747d63"
SERVICE="superflash-xhttp.service"
BASE="/etc/superflash-xhttp"
TLS_DIR="$BASE/tls"
CONFIG="$BASE/config"
BIN="/usr/local/bin/superflash-xhttp-server"
RUNNER="/usr/local/sbin/superflash-xhttp-run"
UNIT="/etc/systemd/system/$SERVICE"
ACME="/root/.acme.sh/acme.sh"
DEFAULT_XHTTP_PORT=443
DEFAULT_SSH_PORT=22
SELF="$(readlink -f "${BASH_SOURCE[0]:-$0}" 2>/dev/null || realpath "${BASH_SOURCE[0]:-$0}" 2>/dev/null || printf '%s' "${BASH_SOURCE[0]:-$0}")"

red='\033[1;31m'; green='\033[1;32m'; cyan='\033[1;36m'; yellow='\033[1;33m'; reset='\033[0m'

need_root(){ if [ "${EUID:-$(id -u)}" -ne 0 ]; then echo -e "${red}Ejecuta como root.${reset}"; exit 1; fi; }
pause(){ echo; read -r -p "Presiona ENTER para continuar..." _ || true; }
valid_port(){ [[ "${1:-}" =~ ^[0-9]+$ ]] && [ "$1" -ge 1 ] && [ "$1" -le 65535 ]; }
valid_domain(){ [[ "${1:-}" =~ ^([A-Za-z0-9]([A-Za-z0-9-]{0,61}[A-Za-z0-9])?\.)+[A-Za-z]{2,63}$ ]]; }
have(){ command -v "$1" >/dev/null 2>&1; }

expected_engine_sha(){
  case "$(uname -m)" in
    x86_64|amd64) echo "$ENGINE_SHA_AMD64" ;;
    aarch64|arm64) echo "$ENGINE_SHA_ARM64" ;;
    *) echo "" ;;
  esac
}
engine_hash(){ [ -f "$BIN" ] && sha256sum "$BIN" 2>/dev/null | awk '{print $1}' || true; }
engine_state(){
  local exp got
  exp="$(expected_engine_sha)"; got="$(engine_hash)"
  if [ -z "$got" ]; then echo "NO INSTALADO"
  elif [ -n "$exp" ] && [ "$got" = "$exp" ]; then echo "ESTABLE v$ENGINE_VERSION"
  else echo "ANTIGUO/OTRO"
  fi
}

load_config(){
  XHTTP_PORT="$DEFAULT_XHTTP_PORT"; SSH_PORT="$DEFAULT_SSH_PORT"; DOMAIN=""; ACME_EMAIL=""
  UFW_RULE_ADDED=0; UFW_RULE_PORT=""
  if [ -f "$CONFIG" ]; then
    # shellcheck disable=SC1090
    . "$CONFIG"
  fi
}
save_config(){
  mkdir -p "$BASE" "$TLS_DIR"
  {
    printf 'XHTTP_PORT=%q\n' "$XHTTP_PORT"
    printf 'SSH_PORT=%q\n' "$SSH_PORT"
    printf 'DOMAIN=%q\n' "$DOMAIN"
    printf 'ACME_EMAIL=%q\n' "$ACME_EMAIL"
    printf 'UFW_RULE_ADDED=%q\n' "$UFW_RULE_ADDED"
    printf 'UFW_RULE_PORT=%q\n' "$UFW_RULE_PORT"
  } > "$CONFIG"
  chmod 600 "$CONFIG"
}

pkg_install_fast(){
  local pkgs=("$@")
  if have apt-get; then
    if DEBIAN_FRONTEND=noninteractive apt-get install -y --no-install-recommends "${pkgs[@]}" >/dev/null 2>&1; then return 0; fi
    echo -e "${yellow}Actualizando índice de paquetes una sola vez...${reset}"
    DEBIAN_FRONTEND=noninteractive apt-get update -y >/dev/null
    DEBIAN_FRONTEND=noninteractive apt-get install -y --no-install-recommends "${pkgs[@]}" >/dev/null
  elif have dnf; then
    dnf install -y "${pkgs[@]}" >/dev/null
  elif have yum; then
    yum install -y "${pkgs[@]}" >/dev/null
  else
    echo -e "${red}No se detectó apt, dnf ni yum.${reset}"
    return 1
  fi
}
ensure_core_deps(){
  local missing=0 c
  for c in base64 gzip tar sha256sum systemctl ss; do have "$c" || missing=1; done
  [ "$missing" -eq 0 ] && return 0
  echo "Instalando dependencias mínimas faltantes..."
  if have apt-get; then pkg_install_fast ca-certificates coreutils gzip tar iproute2
  else pkg_install_fast ca-certificates coreutils gzip tar iproute
  fi
}
ensure_tls_deps(){
  local missing=0 c
  for c in curl openssl socat getent; do have "$c" || missing=1; done
  [ "$missing" -eq 0 ] && return 0
  echo "Instalando herramientas TLS faltantes..."
  if have apt-get; then pkg_install_fast curl ca-certificates openssl socat libc-bin
  else pkg_install_fast curl ca-certificates openssl socat glibc
  fi
}

